    "eStarter": "// [TEACHING SIMULATION — Teaching Model: Explicit State Transition Reducer Engine]\nclass ExplicitStateTransitionReducerEngine {\n  constructor() {\n    this.state = { status: 'idle', data: null, error: null };\n    this.actionHistory = [];\n  }\n  reducer(currentState, action) {\n    // Implement pure transition logic based on currentState.status:\n    // 'idle':\n    //   - 'FETCH_START': return { status: 'loading', data: null, error: null }\n    //   - other actions -> return currentState (reject invalid transition)\n    // 'loading':\n    //   - 'FETCH_SUCCESS': return { status: 'success', data: action.payload, error: null }\n    //   - 'FETCH_FAILURE': return { status: 'error', data: null, error: action.payload }\n    //   - other actions -> return currentState\n    // 'success' | 'error':\n    //   - 'RESET': return { status: 'idle', data: null, error: null }\n    //   - 'FETCH_START': return { status: 'loading', data: null, error: null }\n    //   - other actions -> return currentState\n    \n  }\n  dispatch(action) {\n    this.actionHistory.push(action.type);\n    this.state = this.reducer(this.state, action);\n    return this.state;\n  }\n}",
