    "eTest": "const engine = new DatabaseOptimizationEngine();\nconst before = engine.simulateExplain('SELECT * FROM emp WHERE dept_id = 2', 'dept_id');\nif (before.isIndexed || !before.plan.includes('Seq Scan')) throw new Error('Unindexed query should be Seq Scan');\nengine.createIndex('idx_dept_id', 'emp', 'dept_id');\nconst after = engine.simulateExplain('SELECT * FROM emp WHERE dept_id = 2', 'dept_id');\nif (!after.isIndexed || !after.plan.includes('Index Scan')) throw new Error('Indexed query should be Index Scan');\nconst mig = engine.applyTransactionalMigration(1, ['CREATE TABLE t1 (id INT);', 'CREATE TABLE t2 (id INT);']);\nif (!mig.success || engine.migrations.length !== 1) throw new Error('Transactional migration failed');",
    "aTitle": "HOT Update Qualification Checker",
