    "eStarter": "async function runInIsolatedSchema(db, testCallback) {\n  // Make a unique name like 'test_' + random letters, CREATE SCHEMA it, run the callback,\n  // and DROP SCHEMA ... CASCADE in a finally block.\n  \n}\n\nfunction scanBundleForServerSecrets(bundleText) {\n  // Return false if any forbidden pattern appears, true if the bundle is clean.\n  \n}",
    "eTest": "// A pretend database for this check: it records every SQL statement you send.\nfunction createFakeDb(handler) {\n  const db = { queries: [], async query(sql, params = []) { db.queries.push({ sql, params }); return handler ? handler(sql, params) : { rows: [], rowCount: 0 }; } };\n  return db;\n}\n\nconst db = createFakeDb();\nlet seenName = '';\nawait runInIsolatedSchema(db, async (name) => { seenName = name; });\nif (!/^test_\\w+$/.test(seenName)) throw new Error(\"The schema name must start with 'test_'\");\nif (!db.queries[0] || db.queries[0].sql !== `CREATE SCHEMA ${seenName}`) throw new Error('Create the schema before running the test');\nif (!db.queries[1] || db.queries[1].sql !== `DROP SCHEMA ${seenName} CASCADE`) throw new Error('Drop the schema with CASCADE after the test');\nconst db2 = createFakeDb();\nlet rethrown = false;\ntry { await runInIsolatedSchema(db2, async () => { throw new Error('test failed'); }); } catch (e) { rethrown = e.message === 'test failed'; }\nif (!rethrown) throw new Error('A failing test must still report its error');\nif (!db2.queries.some((q) => /^DROP SCHEMA test_\\w+ CASCADE$/.test(q.sql))) throw new Error('The schema must be dropped even when the test fails');\nlet other = '';\nawait runInIsolatedSchema(createFakeDb(), async (name) => { other = name; });\nif (other === seenName) throw new Error('Every run needs its own unique schema name');\nif (scanBundleForServerSecrets('const x = 1;') !== true) throw new Error('A clean bundle must pass');\nif (scanBundleForServerSecrets('const conn = \"postgres://admin@db\";') !== false) throw new Error('A postgres:// connection string must be caught');\nif (scanBundleForServerSecrets('process.env.SESSION_SECRET') !== false) throw new Error('SESSION_SECRET must be caught');",
