    "eTest": "// Hash helpers the check gives you (the practice sandbox has no Node crypto).\nfunction utf8Bytes(text) { return typeof text === 'string' ? Array.from(new TextEncoder().encode(text)) : Array.from(text); }\nfunction bytesToHex(bytes) { return bytes.map((b) => b.toString(16).padStart(2, '0')).join(''); }\nfunction bytesToBase64(bytes) { return btoa(String.fromCharCode(...bytes)); }\nfunction sha1Bytes(input) {\n  const m = utf8Bytes(input); const len = m.length * 8;\n  m.push(0x80); while (m.length % 64 !== 56) m.push(0);\n  for (let i = 7; i >= 0; i--) m.push(Math.floor(len / 2 ** (8 * i)) & 255);\n  let h = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];\n  for (let o = 0; o < m.length; o += 64) {\n    const w = [];\n    for (let i = 0; i < 16; i++) w[i] = (m[o + 4 * i] << 24) | (m[o + 4 * i + 1] << 16) | (m[o + 4 * i + 2] << 8) | m[o + 4 * i + 3];\n    for (let i = 16; i < 80; i++) { const x = w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]; w[i] = (x << 1) | (x >>> 31); }\n    let [a, b, c, d, e] = h;\n    for (let i = 0; i < 80; i++) {\n      const f = i < 20 ? (b & c) | (~b & d) : i < 40 ? b ^ c ^ d : i < 60 ? (b & c) | (b & d) | (c & d) : b ^ c ^ d;\n      const k = i < 20 ? 0x5a827999 : i < 40 ? 0x6ed9eba1 : i < 60 ? 0x8f1bbcdc : 0xca62c1d6;\n      const t = (((a << 5) | (a >>> 27)) + f + e + k + w[i]) | 0;\n      e = d; d = c; c = (b << 30) | (b >>> 2); b = a; a = t;\n    }\n    h = [h[0] + a, h[1] + b, h[2] + c, h[3] + d, h[4] + e].map((x) => x | 0);\n  }\n  return h.flatMap((x) => [x >>> 24, (x >>> 16) & 255, (x >>> 8) & 255, x & 255]);\n}\nfunction sha256Bytes(input) {\n  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];\n  const m = utf8Bytes(input); const len = m.length * 8;\n  m.push(0x80); while (m.length % 64 !== 56) m.push(0);\n  for (let i = 7; i >= 0; i--) m.push(Math.floor(len / 2 ** (8 * i)) & 255);\n  let h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];\n  const r = (x, n) => (x >>> n) | (x << (32 - n));\n  for (let o = 0; o < m.length; o += 64) {\n    const w = [];\n    for (let i = 0; i < 16; i++) w[i] = (m[o + 4 * i] << 24) | (m[o + 4 * i + 1] << 16) | (m[o + 4 * i + 2] << 8) | m[o + 4 * i + 3];\n    for (let i = 16; i < 64; i++) {\n      const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3);\n      const s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);\n      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;\n    }\n    let [a, b, c, d, e, f, g, hh] = h;\n    for (let i = 0; i < 64; i++) {\n      const t1 = (hh + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;\n      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;\n      hh = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;\n    }\n    h = [h[0] + a, h[1] + b, h[2] + c, h[3] + d, h[4] + e, h[5] + f, h[6] + g, h[7] + hh].map((x) => x | 0);\n  }\n  return h.flatMap((x) => [x >>> 24, (x >>> 16) & 255, (x >>> 8) & 255, x & 255]);\n}\nfunction hmacSha256Bytes(key, message) {\n  let k = utf8Bytes(key);\n  if (k.length > 64) k = sha256Bytes(k);\n  while (k.length < 64) k.push(0);\n  const inner = sha256Bytes(k.map((b) => b ^ 0x36).concat(utf8Bytes(message)));\n  return sha256Bytes(k.map((b) => b ^ 0x5c).concat(inner));\n}\nconst sha1Base64 = (text) => bytesToBase64(sha1Bytes(text));\nconst sha256Hex = (text) => bytesToHex(sha256Bytes(text));\nconst sha256Base64Url = (text) => bytesToBase64(sha256Bytes(text)).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '');\nconst hmacSha256Hex = (key, message) => bytesToHex(hmacSha256Bytes(key, message));\nconst randomHex = (byteCount) => bytesToHex(Array.from(crypto.getRandomValues(new Uint8Array(byteCount))));\n\nconst validator = new DoubleSubmitCsrfValidator('top-secret-signing-key', hmacSha256Hex, randomHex);\nconst token = validator.generateToken('session_alpha');\nif (typeof token !== 'string' || !/^[0-9a-f]{32}\\.[0-9a-f]{64}$/.test(token)) throw new Error('A token is 32 hex characters, a dot, then a 64-character HMAC');\nif (validator.validate(token, token, 'session_alpha').code !== 'OK' || validator.validate(token, token, 'session_alpha').valid !== true) throw new Error('A matching token for the session must be OK');\nif (validator.validate(undefined, token, 'session_alpha').code !== 'CSRF_TOKEN_MISSING') throw new Error('A missing cookie token must give CSRF_TOKEN_MISSING');\nif (validator.validate(token, 12345, 'session_alpha').code !== 'CSRF_TOKEN_MALFORMED') throw new Error('A non-string token must give CSRF_TOKEN_MALFORMED');\nif (validator.validate(token, 'short', 'session_alpha').code !== 'CSRF_TOKEN_WRONG_LENGTH') throw new Error('Tokens of different lengths must give CSRF_TOKEN_WRONG_LENGTH');\nconst flipped = token.slice(0, -1) + (token.endsWith('0') ? '1' : '0');\nif (validator.validate(token, flipped, 'session_alpha').code !== 'CSRF_TOKEN_TAMPERED') throw new Error('A header token that differs from the cookie must give CSRF_TOKEN_TAMPERED');\nif (validator.validate(token, token, 'session_beta').code !== 'CSRF_SESSION_MISMATCH') throw new Error('A token from another session must give CSRF_SESSION_MISMATCH');",
