    "eStarter": "class InMemoryOrderRepo {\n  orders = new Map();\n  async save(order) {\n    // TODO: write your code here\n  }\n  async findById(id) {\n    // TODO: write your code here\n  }\n}\n\nclass OrderService {\n  repo;\n  taxRate;\n  constructor(repo, taxRate) {\n        this.repo = repo;\n        this.taxRate = taxRate;\n    }\n  async createOrder(id, items) {\n    // TODO: write your code here\n  }\n}",
