    "aStarter": "class ECSDeploymentController {\n    calculateRollingCapacity(config) {\n        // Calculate minimum and maximum active tasks permitted during rolling deploy\n        return { minTasks: 0, maxTasks: 0 };\n    }\n    validateTaskDefinition(taskDef) {\n        // Validate CPU and memory conform to valid Fargate ratios\n        return true;\n    }\n}",
    "aHint": "Calculate minTasks by multiplying desiredCount by minimumHealthyPercent divided by one hundred and taking the ceiling. Calculate maxTasks by multiplying desiredCount by maximumPercent divided by one hundred and taking the floor. Validate that memory is at least double the CPU unit value.",
    "aTest": "const controller = new ECSDeploymentController();\nconst capacity = controller.calculateRollingCapacity({\n    serviceName: 'career-api',\n    desiredCount: 4,\n    minimumHealthyPercent: 100,\n    maximumPercent: 200,\n    taskDefinition: { family: 'career-api', cpu: '512', memory: '1024', containerImage: 'career-api:v2' }\n});\nif (capacity.minTasks !== 4 || capacity.maxTasks !== 8) {\n    throw new Error(`Expected min 4, max 8 tasks but got min ${capacity.minTasks}, max ${capacity.maxTasks}`);\n}\nconsole.log('Day 105 Architect tests passed successfully.');"
