    "eDesc": "Implement `function queryLogInsights(logEntries, queryString)` evaluating a structured log query pipeline supporting `filter`, `stats count() by field`, and `sort count desc` against JSON log objects.",
    "eStarter": "function queryLogInsights(logEntries, queryString) {\n  // TODO: Parse pipeline stages separated by '|'\n  // Support: filter <field> <op> <value> (e.g. status >= 500, method == GET)\n  // Support: stats count() by <field>\n  // Support: sort <field> desc | asc\n  return [];\n}",
    "eHint": "Split the incoming query string on the pipe character to isolate each processing stage. Remember to trim whitespace from every stage before extracting the command token. When implementing the stats aggregation stage, accumulate frequency counts inside a dictionary keyed by the grouping field and transform the entries into objects with field and count properties.",
    "eTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst logs = [\n  { status: 200, method: 'GET', path: '/health' },\n  { status: 500, method: 'POST', path: '/orders' },\n  { status: 500, method: 'POST', path: '/checkout' },\n  { status: 503, method: 'GET', path: '/items' }\n];\n\nconst filtered = queryLogInsights(logs, 'filter status >= 500 | stats count() by status | sort count desc');\nassert.ok(filtered.length === 2, 'Should group into 500 and 503');\nassert.ok(filtered[0].status === 500 && filtered[0].count === 2, '500 count should be 2');\nassert.ok(filtered[1].status === 503 && filtered[1].count === 1, '503 count should be 1');\nconsole.log('Day 107 Explorer Tests Passed!');",
