    "aStarter": "class CompositeAlarmEngine {\n  constructor() {\n    this.metricAlarms = new Map();\n    this.compositeAlarms = new Map();\n  }\n\n  registerMetricAlarm(name, m, n, threshold) {\n    // TODO: Track history of data points; trigger ALARM if >= M of last N datapoints exceed threshold\n  }\n\n  recordDatapoint(name, value) {\n    // TODO: Record value and update metric alarm state (OK or ALARM)\n  }\n\n  registerCompositeAlarm(name, ruleFn, suppressorAlarmName = null) {\n    // TODO: ruleFn takes (statesMap) and returns boolean\n  }\n\n  evaluateComposite(name) {\n    // TODO: Return { state: 'ALARM' | 'OK', actionsSuppressed: boolean, reason: string }\n    return { state: 'OK', actionsSuppressed: false, reason: '' };\n  }\n}",
    "aHint": "Store underlying metric datapoint breach booleans in an array capped at size n. Compare the count of true elements against m to determine the metric alarm state. Remember that CloudWatch alarm suppressors suppress composite alarm actions without rewriting the evaluated alarm state; verify that actionsSuppressed is true when the suppressor alarm is in ALARM while preserving the independently calculated composite state.",
    "aTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst engine = new CompositeAlarmEngine();\n\nengine.registerMetricAlarm('HighCPU', 3, 3, 80);\nengine.registerMetricAlarm('High5xx', 3, 3, 10);\nengine.registerMetricAlarm('DeploymentActive', 1, 1, 1);\n\nengine.registerCompositeAlarm('HostDegradation', (states) => states.HighCPU === 'ALARM' && states.High5xx === 'ALARM', 'DeploymentActive');\n\nengine.recordDatapoint('HighCPU', 85);\nengine.recordDatapoint('HighCPU', 90);\nengine.recordDatapoint('HighCPU', 88);\n\nengine.recordDatapoint('High5xx', 15);\nengine.recordDatapoint('High5xx', 12);\nengine.recordDatapoint('High5xx', 14);\n\nconst eval1 = engine.evaluateComposite('HostDegradation');\nassert.ok(eval1.state === 'ALARM' && !eval1.actionsSuppressed, 'Composite should trigger ALARM with actions active');\n\nengine.recordDatapoint('DeploymentActive', 1);\nconst eval2 = engine.evaluateComposite('HostDegradation');\nassert.ok(eval2.state === 'ALARM' && eval2.actionsSuppressed, 'Composite alarm state must remain ALARM while actionsSuppressed is true');\nconsole.log('Day 107 Architect Tests Passed!');"
