    "eTitle": "Universal Scalability Law (USL) Concurrency Modeler",
    "eDesc": "Implement `function calculateUSLThroughput(concurrencyN, sigmaContention, kappaCoherency)` modeling system throughput speedup and identifying retrograde throughput points.",
    "eStarter": "function calculateUSLThroughput(concurrencyN, sigmaContention, kappaCoherency) {\n  // TODO: Compute C(N) = N / (1 + sigma*(N - 1) + kappa*N*(N - 1))\n  // Return { throughput, isRetrograde: boolean }\n  return { throughput: 0, isRetrograde: false };\n}\n\nfunction findPeakConcurrency(sigmaContention, kappaCoherency, maxN = 128) {\n  // TODO: Return N value that produces maximum throughput\n  return 1;\n}",
    "eHint": "Carefully construct the denominator using Dr. Neil Gunther's formula: one plus sigma times (N minus one) plus kappa times N times (N minus one). To determine if concurrency level N is in the retrograde zone, calculate the throughput for N plus one and verify whether it is strictly less than the throughput at N.",
    "eTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst t1 = calculateUSLThroughput(1, 0.05, 0.002);\nassert.ok(t1.throughput === 1, 'At N=1 throughput should be 1');\n\nconst peakN = findPeakConcurrency(0.05, 0.002, 100);\nassert.ok(peakN > 10 && peakN < 40, 'Peak N should be located around 20-25');\nconst atPeak = calculateUSLThroughput(peakN, 0.05, 0.002);\nassert.ok(atPeak.isRetrograde === true, 'Next step beyond peak should be retrograde');\nconsole.log('Day 108 Explorer Tests Passed!');",
    "aTitle": "CDN Edge Cache Simulator with Stale-While-Revalidate",
    "aDesc": "Implement `class EdgeCacheSimulator` evaluating `Cache-Control` header directives (`s-maxage`, `stale-while-revalidate`), request collapsing for in-flight cache misses, and background origin revalidation. Count every call to the origin in this.originCallCount. fetch(url, nowMs) returns { body, status, originCalls }: 'HIT' while the entry is younger than sMaxAge seconds, 'STALE_HIT' (and a background refresh) within the extra staleWhileRevalidate seconds, otherwise 'MISS'. Concurrent misses for the same URL must share one origin call.",
    "aStarter": "class EdgeCacheSimulator {\n  constructor(originFetchFn) {\n    this.originFetchFn = originFetchFn;\n    this.cache = new Map();\n    this.inFlightRequests = new Map();\n  }\n\n  async fetch(url, nowMs) {\n    // TODO: Return { body, status: 'HIT' | 'STALE_HIT' | 'MISS', originCalls: number }\n  }\n}",
    "aHint": "Keep a Map of in-flight promises keyed by target URL. When concurrent misses arrive for the identical URL, have them await the single existing promise rather than initiating new origin requests. In stale-while-revalidate evaluation, verify if the elapsed age is between s-maxage and s-maxage plus stale-while-revalidate. Return the cached body immediately with STALE_HIT while triggering background revalidation.",
    "aTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nawait (async () => {\n  let originCounter = 0;\n  const mockOrigin = async (url) => ({\n    body: 'payload_' + (++originCounter),\n    sMaxAge: 2,\n    staleWhileRevalidate: 5\n  });\n\n  const cdn = new EdgeCacheSimulator(mockOrigin);\n\n  const [res1, res2] = await Promise.all([\n    cdn.fetch('/api/data', 1000),\n    cdn.fetch('/api/data', 1000)\n  ]);\n  assert.ok(res1.status === 'MISS' && res2.status === 'MISS', 'Both should report miss');\n  assert.ok(cdn.originCallCount === 1, 'Origin calls should be collapsed to 1');\n\n  const res3 = await cdn.fetch('/api/data', 2000);\n  assert.ok(res3.status === 'HIT', 'Should be HIT within sMaxAge');\n  assert.ok(cdn.originCallCount === 1, 'Origin call count must not increase');\n\n  const res4 = await cdn.fetch('/api/data', 4000);\n  assert.ok(res4.status === 'STALE_HIT', 'Should be STALE_HIT');\n\n  console.log('Day 108 Architect Tests Passed!');\n})();"
