    "eStarter": "function parseAndValidateLLMOutput(rawResponse) {\n  // Parse rawResponse safely and validate:\n  // summary: string (non-empty)\n  // confidenceScore: number between 0 and 1 inclusive\n  // tags: array of strings\n  // Return { valid: true, data } or { valid: false, errorType }\n}",
