    "eTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst validRaw = JSON.stringify({ summary: \"System design analysis\", confidenceScore: 0.95, tags: [\"distributed\", \"scaling\"] });\nconst res1 = parseAndValidateLLMOutput(validRaw);\nassert.strictEqual(res1.valid, true);\nassert.strictEqual(res1.data.confidenceScore, 0.95);\n\nconst malformedRaw = 'Not valid JSON';\nconst res2 = parseAndValidateLLMOutput(malformedRaw);\nassert.strictEqual(res2.valid, false);\nassert.strictEqual(res2.errorType, 'SYNTAX_ERROR');\n\nconst invalidFieldsRaw = JSON.stringify({ summary: \"\", confidenceScore: 1.5, tags: \"not-array\" });\nconst res3 = parseAndValidateLLMOutput(invalidFieldsRaw);\nassert.strictEqual(res3.valid, false);\nassert.strictEqual(res3.errorType, 'SCHEMA_ERROR');",
    "aTitle": "Architect: LLM Token Budget Controller & Rate-Limit Backoff",
    "aDesc": "Construct an LLM token budget and rate-limit controller class that tracks cumulative tokens consumed per minute, rejects calls that exceed the configured minute quota, and applies exponential backoff with full jitter when external calls return HTTP 429 status codes.",
    "aStarter": "class LLMTokenBudgetController {\n  constructor(tokensPerMinuteLimit) {\n    this.limit = tokensPerMinuteLimit;\n    this.consumed = 0;\n  }\n\n  canConsume(tokenEstimate) {\n    // Check if adding tokenEstimate exceeds this.limit\n  }\n\n  recordConsumption(actualTokens) {\n    // Increment consumed tokens\n  }\n\n  calculateRetryDelayMs(attempt, baseDelayMs = 100) {\n    // Calculate exponential backoff with full jitter: uniform random in [0, baseDelayMs * 2^attempt]\n  }\n}",
    "aHint": "In canConsume check that this.consumed plus tokenEstimate is less than or equal to this.limit, returning a boolean to prevent quota overruns before sending requests. In calculateRetryDelayMs calculate the exponential ceiling as baseDelayMs multiplied by two raised to the attempt power, then multiply by Math.random to implement full jitter.",
    "aTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst controller = new LLMTokenBudgetController(1000);\nassert.strictEqual(controller.canConsume(600), true);\ncontroller.recordConsumption(600);\nassert.strictEqual(controller.canConsume(500), false);\nassert.strictEqual(controller.canConsume(400), true);\n\nfor (let i = 0; i < 50; i++) {\n  const delay = controller.calculateRetryDelayMs(3, 100);\n  assert.ok(delay >= 0 && delay <= 800, 'Delay must fall within [0, 800ms] for attempt 3');\n}"
