    "eStarter": "function computeL2Norm(v) {\n  // Compute sqrt of sum of squares\n}\n\nfunction normalizeVector(v) {\n  // Return new array with elements divided by L2 norm; handle zero vector\n}\n\nfunction computeDotProduct(u, v) {\n  // Compute sum of u[i] * v[i]; throw on dimension mismatch\n}",
    "eHint": "For computeL2Norm iterate through vector elements, accumulate the square of each element, and return Math.sqrt of the accumulated sum, ensuring floating point accuracy. In computeDotProduct first verify that u.length equals v.length to avoid out of bound errors, then compute and return the scalar sum of element products across dimensions.",
    "eTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst v = [3, 4];\nassert.strictEqual(computeL2Norm(v), 5);\nconst normV = normalizeVector(v);\nassert.ok(Math.abs(normV[0] - 0.6) < 1e-6);\nassert.ok(Math.abs(normV[1] - 0.8) < 1e-6);\nassert.ok(Math.abs(computeL2Norm(normV) - 1.0) < 1e-6);\n\nconst u = [1, 2, 3];\nconst w = [4, 5, 6];\nassert.strictEqual(computeDotProduct(u, w), 32); // 4 + 10 + 18 = 32",
    "aTitle": "Architect: Nearest-Neighbor Semantic Retrieval Engine",
    "aDesc": "Build an in-memory nearest-neighbor semantic retrieval class that indexes a collection of document vectors, computes Cosine Distance: 1 - (u . v) / (||u|| * ||v||), and returns the top-K closest documents sorted in ascending order of distance.",
    "aStarter": "class SemanticVectorIndex {\n  constructor() {\n    this.documents = [];\n  }\n\n  insert(id, vector, metadata = {}) {\n    // Store document record\n  }\n\n  searchTopK(queryVector, k = 3) {\n    // Compute Cosine Distance to every document\n    // Return top K documents sorted ascending by distance\n  }\n}",
    "aHint": "For each stored document, calculate the dot product, query norm, and document norm, then derive cosine distance as one minus the quotient of dot product and multiplied norms. Sort the computed results array in ascending order of distance and slice the first k elements, returning objects containing id, distance, and metadata for inspection.",
    "aTest": "// A small stand-in for Node's assert module (the browser does not have it).\nconst assert = (() => {\n  const fail = (message, fallback) => { throw new Error(message || fallback); };\n  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);\n  const ok = (value, message) => { if (!value) fail(message, 'Expected a truthy value'); };\n  ok.ok = ok;\n  ok.strictEqual = (a, b, message) => { if (a !== b) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.notStrictEqual = (a, b, message) => { if (a === b) fail(message, 'Expected a value other than ' + JSON.stringify(b)); };\n  ok.deepStrictEqual = (a, b, message) => { if (!same(a, b)) fail(message, 'Expected ' + JSON.stringify(b) + ' but got ' + JSON.stringify(a)); };\n  ok.throws = (fn, _expected, message) => { let threw = false; try { fn(); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the function to throw'); };\n  ok.rejects = async (fnOrPromise, _expected, message) => { let threw = false; try { await (typeof fnOrPromise === 'function' ? fnOrPromise() : fnOrPromise); } catch { threw = true; } if (!threw) fail(typeof _expected === 'string' ? _expected : message, 'Expected the promise to reject'); };\n  return ok;\n})();\n\nconst index = new SemanticVectorIndex();\nindex.insert('doc-1', [1, 0, 0], { title: 'Cosmology' });\nindex.insert('doc-2', [0.9, 0.1, 0], { title: 'Astronomy' });\nindex.insert('doc-3', [0, 1, 0], { title: 'Cooking' });\n\nconst results = index.searchTopK([1, 0, 0], 2);\nassert.strictEqual(results.length, 2);\nassert.strictEqual(results[0].id, 'doc-1');\nassert.ok(Math.abs(results[0].distance - 0.0) < 1e-6);\nassert.strictEqual(results[1].id, 'doc-2');\nassert.ok(results[1].distance < 0.1);"
